delete from FCM_MENU WHERE (MENU_ID LIKE 'MS%' OR MENU_ID LIKE 'MBBEP0080_MS%') AND (PARENT_MENU_ID = 'MCF' OR PARENT_MENU_ID LIKE 'MCF,MB%') ;

delete from FCM_MENU WHERE PARENT_MENU_ID LIKE 'MCF,MS%' ;


